/* ═══════════════════════════════════════════════════════════════════════
   RESEARCH ARTIFACT LINKS CARD  (.ds-artifact-links)
   ───────────────────────────────────────────────────────────────────────
   A card listing a paper's external research artifacts — datasets, code
   repositories, supplementary material. Appears on the abstract page as
   browsable supplementary material, not a primary call to action.
   Suitable for the sidebar rail or as a standalone supplement card.

   Each row is an <a class="ds-artifact-row"> that opens off-site in a
   new tab. Three pieces of information per row:
     .ds-artifact-label    — artifact type ("Training data", "Code")
     .ds-artifact-dest     — destination platform ("Zenodo", "GitHub")
     .ds-artifact-ext-icon — external-link arrow (aria-hidden="true")
   A .is-sr-only "(opens in new tab)" span inside every <a> tells AT
   the link opens off-site (WCAG 1.4.1 — never intent by color alone).

   Row states:
     Hover  — Active Wash background (--arxiv-active-bg), the shared
              "arXiv-chrome interactive surface" wash.
     Focus  — 3px Link Blue ring inset (-2px offset) via :focus-visible.
     Visited — Row stays ink-colored; suppress the default visited-purple
              so the list reads as a stable set, not a history display.

   Overflow threshold: 1–5 rows render without scroll. For 6+ rows add
   .ds-artifact-list--scroll to the <ul>, set tabindex="0", and supply
   aria-label="N research artifacts — scroll for more". Height is set to
   ~4.5 × row height so the last visible item is cut mid-item — the
   half-item-peek from DESIGN-POLICIES.md "Truncation always signals
   continuation." DESIGN-POLICIES.md prefers an explicit-count disclosure
   first; the half-item peek is the approved visual fallback when a
   separate "show all" control would add unnecessary friction to a short
   browsable list.

   No new tokens — uses: --arxiv-border-light (card edge / row dividers),
   --arxiv-active-bg (hover wash), --arxiv-focus-ring (focus ring),
   --arxiv-ink (row text), --arxiv-grey (dest badge, visited row),
   --arxiv-grey-ui (ext-link icon at rest), --arxiv-font-sans /
   --arxiv-font-condensed.

   Example (1–5 rows):
     <section class="ds-artifact-links" aria-labelledby="artf-hd">
       <h2 class="ds-artifact-links-title" id="artf-hd">
         Research artifacts
       </h2>
       <ul class="ds-artifact-list" role="list">
         <li>
           <a class="ds-artifact-row" href="https://zenodo.org/…"
              target="_blank" rel="noopener noreferrer">
             <span class="ds-artifact-label">Training data</span>
             <span class="ds-artifact-dest">Zenodo</span>
             <svg class="ds-artifact-ext-icon" aria-hidden="true"
                  viewBox="0 0 12 12" fill="none" stroke="currentColor"
                  stroke-width="1.5" stroke-linecap="round"
                  stroke-linejoin="round">
               <path d="M3.5 8.5L9 3M5.5 3H9V6.5"/>
             </svg>
             <span class="is-sr-only">(opens in new tab)</span>
           </a>
         </li>
       </ul>
     </section>

   Example (6+ rows — add the scroll modifier):
     <ul class="ds-artifact-list ds-artifact-list--scroll"
         tabindex="0" role="list"
         aria-label="12 research artifacts — scroll for more">…</ul>

   Reference: docs/public/artifact-links-styles.html.
   ═══════════════════════════════════════════════════════════════════════ */

/* Card shell — white surface, hairline border, 8px radius on Warm Wash
   page background. overflow:hidden clips row hover/focus to the corners. */
.ds-artifact-links {
  background: #ffffff;
  border: 1px solid var(--arxiv-border-light);
  border-radius: 8px;
  font-family: var(--arxiv-font-sans);
  overflow: hidden;
}

/* Card title bar — same weight and scale as .ds-acc summary. */
.ds-artifact-links-title {
  margin: 0;
  padding: 11px 16px;
  font-size: 0.875rem; /* 14px at 16px root */
  font-weight: 600;
  color: var(--arxiv-ink);
  border-bottom: 1px solid var(--arxiv-border-light);
}

/* List of artifact rows. */
.ds-artifact-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

/* Overflow variant — 6+ rows. Row height ≈ 40px (14px text × 1.5
   line-height ≈ 21px + 10px×2 padding + 1px border). 4.5 × 40px = 180px.
   The cut bottom row is the geometric truncation signal. */
.ds-artifact-list--scroll {
  max-height: 180px;
  overflow-y: auto;
  overscroll-behavior: contain;
}

/* Each artifact is a full-width <a> inside a <li>.
   Three-column grid: label (fluid) | dest badge (compact) | icon (fixed). */
.ds-artifact-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  align-items: center;
  gap: 0 10px;
  padding: 10px 14px;
  text-decoration: none;
  color: var(--arxiv-ink);
  border-bottom: 1px solid var(--arxiv-border-light);
  transition: background 0.12s;
}
.ds-artifact-list li:last-child .ds-artifact-row { border-bottom: none; }

.ds-artifact-row:visited { color: var(--arxiv-ink); }

.ds-artifact-row:hover {
  background: var(--arxiv-active-bg);
}
.ds-artifact-row:focus-visible {
  outline: 3px solid var(--arxiv-focus-ring);
  outline-offset: -2px;
  border-radius: 2px;
}

/* Artifact type — primary label, body weight. */
.ds-artifact-label {
  font-size: 0.8125rem; /* 13px */
  font-weight: 500;
  color: var(--arxiv-ink);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Destination platform — condensed-caps badge, muted weight. */
.ds-artifact-dest {
  font-family: var(--arxiv-font-condensed);
  font-size: 0.6875rem; /* 11px */
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--arxiv-grey);
  white-space: nowrap;
}

/* External-link arrow — purely decorative (aria-hidden); color steps
   up from grey-ui to grey on hover for a light acknowledgment. */
.ds-artifact-ext-icon {
  display: block;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  color: var(--arxiv-grey-ui);
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: color 0.12s;
}
.ds-artifact-row:hover .ds-artifact-ext-icon { color: var(--arxiv-grey); }

@media (prefers-reduced-motion: reduce) {
  .ds-artifact-row,
  .ds-artifact-ext-icon { transition: none; }
}

@media (forced-colors: active) {
  .ds-artifact-links { border-color: ButtonBorder; }
  .ds-artifact-row   { border-color: ButtonBorder; }
  .ds-artifact-row:hover  { background: Highlight; color: HighlightText; }
  .ds-artifact-ext-icon   { color: LinkText; }
}

